#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    int maxCapacity(vector<int>& costs, int budget) {
        long long total = accumulate(costs.begin(), costs.end(), 0LL);
        if (total == 0) return budget;
        return budget / total;
    }
};

class Solution {
    public int maxCapacity(int[] costs, int budget) {
        long total = 0;
        for (int c : costs) total += c;
        if (total == 0) return budget;
        return (int)(budget / total);
    }
}

var maxCapacity = function(costs, budget) {
    const total = costs.reduce((a, b) => a + b, 0);
    if (total === 0) return budget;
    return Math.floor(budget / total);
};
